package com.cameralock;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class CameraLockPanel extends PluginPanel
{
	private static final Color LOCKED_COLOR = new Color(220, 50, 50);
	private static final Color UNLOCKED_COLOR = new Color(80, 200, 80);
	private static final Color ACTIVE_BORDER_COLOR = new Color(80, 200, 80);
	private static final Color GUIDANCE_BORDER_COLOR = new Color(255, 152, 31);

	// All three borders must have identical total insets to prevent row resizing on state changes
	private static final Border INACTIVE_ROW_BORDER = BorderFactory.createCompoundBorder(
		BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1),
		new EmptyBorder(3, 5, 3, 5)
	);
	private static final Border ACTIVE_ROW_BORDER = BorderFactory.createCompoundBorder(
		BorderFactory.createLineBorder(ACTIVE_BORDER_COLOR, 1),
		new EmptyBorder(3, 5, 3, 5)
	);
	private static final Border GUIDANCE_ROW_BORDER = BorderFactory.createCompoundBorder(
		BorderFactory.createLineBorder(GUIDANCE_BORDER_COLOR, 1),
		new EmptyBorder(3, 5, 3, 5)
	);

	private final CameraLockPlugin plugin;
	private final JLabel statusLabel;
	private final JButton toggleButton;
	private final JPanel presetListPanel;
	private final JTextField nameField;

	private final List<JPanel> presetRows = new ArrayList<>();
	private final List<JButton> lockButtons = new ArrayList<>();
	private int guidanceIndex = -1;

	CameraLockPanel(CameraLockPlugin plugin)
	{
		super();
		this.plugin = plugin;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		// ── Header row ──────────────────────────────────────────────────────
		JLabel title = new JLabel("Camera Locks");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());

		statusLabel = new JLabel("UNLOCKED", SwingConstants.RIGHT);
		statusLabel.setForeground(UNLOCKED_COLOR);
		statusLabel.setFont(FontManager.getRunescapeBoldFont());

		JPanel headerRow = row();
		headerRow.add(title, BorderLayout.WEST);
		headerRow.add(statusLabel, BorderLayout.EAST);
		headerRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, headerRow.getPreferredSize().height));

		// ── Toggle button (stable width so text swap does not cause reflow) ─
		toggleButton = new JButton("Lock Camera");
		toggleButton.setPreferredSize(new Dimension(140, 28));
		toggleButton.setMaximumSize(new Dimension(140, 28));
		toggleButton.setMinimumSize(new Dimension(140, 28));
		toggleButton.addActionListener(e -> plugin.toggleLock());

		JPanel toggleWrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		toggleWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		toggleWrapper.setAlignmentX(LEFT_ALIGNMENT);
		toggleWrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		toggleWrapper.add(toggleButton);

		// ── Save section ────────────────────────────────────────────────────
		JLabel saveLabel = sectionLabel("Save Position:");

		nameField = new JTextField();
		nameField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		nameField.setForeground(Color.WHITE);
		nameField.setCaretColor(Color.WHITE);

		JButton addButton = new JButton("+");
		addButton.setPreferredSize(new Dimension(30, 26));
		addButton.setMinimumSize(new Dimension(30, 26));
		addButton.setMaximumSize(new Dimension(30, 26));
		addButton.setFont(addButton.getFont().deriveFont(Font.BOLD, 14f));
		addButton.setToolTipText("Save current camera position");
		addButton.addActionListener(e ->
		{
			String name = nameField.getText().trim();
			if (!name.isEmpty())
			{
				plugin.savePreset(name);
				nameField.setText("");
			}
		});

		JPanel saveRow = row();
		saveRow.add(nameField, BorderLayout.CENTER);
		saveRow.add(addButton, BorderLayout.EAST);
		saveRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		// ── Preset list section ─────────────────────────────────────────────
		JLabel presetsLabel = sectionLabel("Saved Positions:");

		presetListPanel = new JPanel();
		presetListPanel.setLayout(new BoxLayout(presetListPanel, BoxLayout.Y_AXIS));
		presetListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		presetListPanel.setAlignmentX(LEFT_ALIGNMENT);

		// ── Assemble ────────────────────────────────────────────────────────
		add(headerRow);
		add(Box.createVerticalStrut(10));
		add(toggleWrapper);
		add(Box.createVerticalStrut(18));
		add(saveLabel);
		add(Box.createVerticalStrut(3));
		add(saveRow);
		add(Box.createVerticalStrut(12));
		add(presetsLabel);
		add(Box.createVerticalStrut(4));
		add(presetListPanel);
	}

	private JPanel row()
	{
		JPanel p = new JPanel(new BorderLayout(4, 0));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	private JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setAlignmentX(LEFT_ALIGNMENT);
		label.setMaximumSize(new Dimension(Integer.MAX_VALUE, label.getPreferredSize().height));
		return label;
	}

	void setLocked(boolean locked)
	{
		SwingUtilities.invokeLater(() ->
		{
			statusLabel.setText(locked ? "LOCKED" : "UNLOCKED");
			statusLabel.setForeground(locked ? LOCKED_COLOR : UNLOCKED_COLOR);
			toggleButton.setText(locked ? "Unlock Camera" : "Lock Camera");
		});
	}

	/**
	 * Highlight a preset row as "aligning" (orange border, disabled button showing "···").
	 * Pass -1 to clear all guidance highlighting.
	 */
	void setGuidancePreset(int index)
	{
		SwingUtilities.invokeLater(() ->
		{
			// Clear previous guidance row
			if (guidanceIndex >= 0 && guidanceIndex < presetRows.size())
			{
				presetRows.get(guidanceIndex).setBorder(INACTIVE_ROW_BORDER);
				lockButtons.get(guidanceIndex).setText("LOCK");
				lockButtons.get(guidanceIndex).setEnabled(true);
			}

			guidanceIndex = index;

			if (index >= 0 && index < presetRows.size())
			{
				presetRows.get(index).setBorder(GUIDANCE_ROW_BORDER);
				lockButtons.get(index).setText("···");
				lockButtons.get(index).setEnabled(false);
				statusLabel.setText("ALIGNING");
				statusLabel.setForeground(GUIDANCE_BORDER_COLOR);
				toggleButton.setText("Cancel");
			}
		});
	}

	/**
	 * Mark a preset row as locked (green border, "LOCKED" button).
	 * Clears any guidance styling. Pass -1 to clear all active highlighting.
	 */
	void setActivePreset(int index)
	{
		SwingUtilities.invokeLater(() ->
		{
			guidanceIndex = -1;
			for (int i = 0; i < presetRows.size(); i++)
			{
				boolean active = (i == index);
				presetRows.get(i).setBorder(active ? ACTIVE_ROW_BORDER : INACTIVE_ROW_BORDER);
				if (i < lockButtons.size())
				{
					JButton btn = lockButtons.get(i);
					btn.setText(active ? "LOCKED" : "LOCK");
					btn.setEnabled(!active);
				}
			}
		});
	}

	void refreshPresets(List<CameraPreset> presets)
	{
		SwingUtilities.invokeLater(() ->
		{
			presetListPanel.removeAll();
			presetRows.clear();
			lockButtons.clear();
			guidanceIndex = -1;

			if (presets.isEmpty())
			{
				JLabel empty = sectionLabel("No positions saved yet");
				presetListPanel.add(empty);
			}
			else
			{
				for (int i = 0; i < presets.size(); i++)
				{
					JPanel rowPanel = buildPresetRow(presets.get(i), i);
					presetRows.add(rowPanel);
					presetListPanel.add(rowPanel);
					if (i < presets.size() - 1)
					{
						presetListPanel.add(Box.createVerticalStrut(3));
					}
				}
			}

			presetListPanel.revalidate();
			presetListPanel.repaint();
		});
	}

	private JPanel buildPresetRow(CameraPreset preset, int index)
	{
		JPanel rowPanel = row();
		rowPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		rowPanel.setBorder(INACTIVE_ROW_BORDER);

		int rowH = 28;
		rowPanel.setPreferredSize(new Dimension(0, rowH));
		rowPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowH));
		rowPanel.setMinimumSize(new Dimension(0, rowH));

		JLabel nameLabel = new JLabel(preset.getName());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());

		JButton lockButton = new JButton("LOCK");
		lockButton.setPreferredSize(new Dimension(68, 20));
		lockButton.setMinimumSize(new Dimension(68, 20));
		lockButton.setMaximumSize(new Dimension(68, 20));
		lockButton.setFont(lockButton.getFont().deriveFont(Font.BOLD, 10f));
		lockButton.setToolTipText("Guide camera to this position and lock");
		lockButton.addActionListener(e -> plugin.startGuidance(preset));
		lockButtons.add(lockButton);

		JButton deleteButton = new JButton("✕");
		deleteButton.setPreferredSize(new Dimension(26, 20));
		deleteButton.setMinimumSize(new Dimension(26, 20));
		deleteButton.setMaximumSize(new Dimension(26, 20));
		deleteButton.setForeground(new Color(200, 50, 50));
		deleteButton.setToolTipText("Delete preset");
		deleteButton.addActionListener(e -> plugin.deletePreset(index));

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		buttons.add(lockButton);
		buttons.add(deleteButton);

		rowPanel.add(nameLabel, BorderLayout.CENTER);
		rowPanel.add(buttons, BorderLayout.EAST);
		return rowPanel;
	}
}

package com.cameralock;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
	name = "Camera Locks",
	description = "Lock the camera and save/restore named camera position presets",
	tags = {"camera", "lock", "zoom", "pan", "preset"}
)
public class CameraLockPlugin extends Plugin implements KeyListener, MouseListener, MouseWheelListener
{
	static final int YAW_TOLERANCE = 15;
	static final int PITCH_TOLERANCE = 8;
	static final int ZOOM_TOLERANCE = 50;

	private static final String CONFIG_GROUP = "cameralock";
	private static final String PRESETS_KEY = "presets";
	private static final Type PRESET_LIST_TYPE = new TypeToken<List<CameraPreset>>(){}.getType();

	@Inject
	private CameraLockConfig config;

	@Inject
	private Client client;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private CameraLockOverlay overlay;

	private CameraLockPanel panel;

	@Getter
	private boolean locked = false;

	@Getter
	private CameraPreset guidancePreset = null;
	private int guidancePresetIndex = -1;

	private int activePresetIndex = -1;
	private boolean middleMouseDown = false;
	private NavigationButton navButton;

	private final HotkeyListener toggleHotkeyListener = new HotkeyListener(() -> config.toggleHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			toggleLock();
		}
	};

	@Provides
	CameraLockConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CameraLockConfig.class);
	}

	@Override
	protected void startUp()
	{
		locked = false;
		guidancePreset = null;
		guidancePresetIndex = -1;
		activePresetIndex = -1;
		middleMouseDown = false;

		panel = new CameraLockPanel(this);

		navButton = NavigationButton.builder()
			.tooltip("Camera Locks")
			.icon(buildIcon())
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		panel.refreshPresets(loadPresets());

		keyManager.registerKeyListener(toggleHotkeyListener);
		keyManager.registerKeyListener(this);
		mouseManager.registerMouseListener(this);
		mouseManager.registerMouseWheelListener(this);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		locked = false;
		guidancePreset = null;
		guidancePresetIndex = -1;
		activePresetIndex = -1;
		middleMouseDown = false;
		client.setCameraSpeed(1f);

		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;

		keyManager.unregisterKeyListener(toggleHotkeyListener);
		keyManager.unregisterKeyListener(this);
		mouseManager.unregisterMouseListener(this);
		mouseManager.unregisterMouseWheelListener(this);
		overlayManager.remove(overlay);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (guidancePreset == null)
		{
			return;
		}

		int yaw = client.getCameraYaw();
		int pitch = client.getCameraPitch();
		int zoom = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);

		boolean yawOk = Math.abs(yawDiff(guidancePreset.getYaw(), yaw)) <= YAW_TOLERANCE;
		boolean pitchOk = Math.abs(guidancePreset.getPitch() - pitch) <= PITCH_TOLERANCE;
		boolean zoomOk = Math.abs(guidancePreset.getZoom() - zoom) <= ZOOM_TOLERANCE;

		if (yawOk && pitchOk && zoomOk)
		{
			guidancePreset = null;
			activePresetIndex = guidancePresetIndex;
			guidancePresetIndex = -1;
			locked = true;
			client.setCameraSpeed(1f);
			panel.setLocked(true);
			panel.setActivePreset(activePresetIndex);
		}
	}

	/** Signed circular difference: positive = target is clockwise from current. */
	static int yawDiff(int target, int current)
	{
		int diff = target - current;
		if (diff > 1024) diff -= 2048;
		if (diff < -1024) diff += 2048;
		return diff;
	}

	void toggleLock()
	{
		if (guidancePreset != null)
		{
			// Cancel guidance
			guidancePreset = null;
			guidancePresetIndex = -1;
			client.setCameraSpeed(1f);
			panel.setGuidancePreset(-1);
			panel.setLocked(false);
			return;
		}

		locked = !locked;
		if (!locked)
		{
			middleMouseDown = false;
			activePresetIndex = -1;
			panel.setActivePreset(-1);
		}
		panel.setLocked(locked);
	}

	void savePreset(String name)
	{
		int yaw = client.getCameraYaw();
		int pitch = client.getCameraPitch();
		int zoom = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);

		List<CameraPreset> presets = loadPresets();
		presets.add(new CameraPreset(name, yaw, pitch, zoom));
		storePresets(presets);
		panel.refreshPresets(presets);
		panel.setActivePreset(activePresetIndex);
	}

	void startGuidance(CameraPreset preset)
	{
		List<CameraPreset> presets = loadPresets();
		int index = presets.indexOf(preset);

		// Unlock the camera so the user can move it
		locked = false;
		middleMouseDown = false;

		guidancePreset = preset;
		guidancePresetIndex = index;
		activePresetIndex = -1;

		client.setCameraSpeed(0.1f);

		panel.setLocked(false);
		panel.setActivePreset(-1);
		panel.setGuidancePreset(index);
	}

	void deletePreset(int index)
	{
		List<CameraPreset> presets = loadPresets();
		if (index < 0 || index >= presets.size())
		{
			return;
		}
		presets.remove(index);
		storePresets(presets);

		if (guidancePresetIndex == index)
		{
			guidancePreset = null;
			guidancePresetIndex = -1;
		}
		else if (guidancePresetIndex > index)
		{
			guidancePresetIndex--;
		}

		if (activePresetIndex == index)
		{
			activePresetIndex = -1;
		}
		else if (activePresetIndex > index)
		{
			activePresetIndex--;
		}

		panel.refreshPresets(presets);
		panel.setGuidancePreset(guidancePresetIndex);
		panel.setActivePreset(activePresetIndex);
	}

	private List<CameraPreset> loadPresets()
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, PRESETS_KEY);
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<CameraPreset> result = gson.fromJson(json, PRESET_LIST_TYPE);
			return result != null ? result : new ArrayList<>();
		}
		catch (Exception e)
		{
			log.error("Failed to deserialize camera presets", e);
			return new ArrayList<>();
		}
	}

	private void storePresets(List<CameraPreset> presets)
	{
		configManager.setConfiguration(CONFIG_GROUP, PRESETS_KEY, gson.toJson(presets));
	}

	private static BufferedImage buildIcon()
	{
		final int S = 16;
		BufferedImage img = new BufferedImage(S, S, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g.setColor(new Color(255, 152, 31));
		g.fillRoundRect(1, 4, 12, 9, 2, 2);
		g.fillRoundRect(5, 2, 4, 3, 1, 1);

		g.setColor(new Color(18, 18, 24));
		g.fillOval(4, 5, 7, 7);
		g.setColor(new Color(80, 44, 6));
		g.fillOval(5, 6, 5, 5);
		g.setColor(new Color(255, 230, 180, 150));
		g.fillOval(6, 7, 2, 2);

		g.setColor(new Color(180, 90, 10));
		g.fillOval(11, 4, 3, 3);

		g.dispose();
		return img;
	}

	// region KeyListener

	@Override
	public void keyTyped(KeyEvent e) {}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!locked || !config.lockArrowKeys()) return;
		int code = e.getKeyCode();
		if (code == KeyEvent.VK_UP || code == KeyEvent.VK_DOWN
			|| code == KeyEvent.VK_LEFT || code == KeyEvent.VK_RIGHT)
		{
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (!locked || !config.lockArrowKeys()) return;
		int code = e.getKeyCode();
		if (code == KeyEvent.VK_UP || code == KeyEvent.VK_DOWN
			|| code == KeyEvent.VK_LEFT || code == KeyEvent.VK_RIGHT)
		{
			e.consume();
		}
	}

	// endregion

	// region MouseListener

	@Override
	public MouseEvent mousePressed(MouseEvent mouseEvent)
	{
		if (!locked || !config.lockMiddleMouse()) return mouseEvent;
		if (SwingUtilities.isMiddleMouseButton(mouseEvent))
		{
			middleMouseDown = true;
			mouseEvent.consume();
		}
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent mouseEvent)
	{
		if (SwingUtilities.isMiddleMouseButton(mouseEvent) && middleMouseDown)
		{
			middleMouseDown = false;
			if (locked && config.lockMiddleMouse()) mouseEvent.consume();
		}
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent mouseEvent)
	{
		if (locked && config.lockMiddleMouse() && middleMouseDown) mouseEvent.consume();
		return mouseEvent;
	}

	@Override public MouseEvent mouseClicked(MouseEvent e) { return e; }
	@Override public MouseEvent mouseEntered(MouseEvent e) { return e; }
	@Override public MouseEvent mouseExited(MouseEvent e) { return e; }
	@Override public MouseEvent mouseMoved(MouseEvent e) { return e; }

	// endregion

	// region MouseWheelListener

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent mouseWheelEvent)
	{
		if (locked && config.lockScroll()) mouseWheelEvent.consume();
		return mouseWheelEvent;
	}

	// endregion
}

package com.cameralock;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.event.KeyEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.config.Keybind;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class CameraLockOverlay extends Overlay
{
	private static final Color LOCKED_RED = new Color(220, 50, 50);
	private static final Color ALIGN_ORANGE = new Color(255, 152, 31);
	private static final Color OK_GREEN = new Color(80, 200, 80);
	private static final Color HINT_COLOR = new Color(180, 180, 180);

	private final CameraLockPlugin plugin;
	private final CameraLockConfig config;
	private final Client client;
	private final PanelComponent panelComponent = new PanelComponent();

	@Inject
	CameraLockOverlay(CameraLockPlugin plugin, CameraLockConfig config, Client client)
	{
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		CameraPreset guidance = plugin.getGuidancePreset();
		if (guidance != null)
		{
			return renderGuidance(graphics, guidance);
		}

		if (plugin.isLocked() && config.showOverlay())
		{
			return renderLocked(graphics);
		}

		return null;
	}

	private Dimension renderGuidance(Graphics2D graphics, CameraPreset target)
	{
		int yaw = client.getCameraYaw();
		int pitch = client.getCameraPitch();
		int zoom = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);

		int yd = CameraLockPlugin.yawDiff(target.getYaw(), yaw);
		int pd = target.getPitch() - pitch;
		int zd = target.getZoom() - zoom;

		boolean yOk = Math.abs(yd) <= CameraLockPlugin.YAW_TOLERANCE;
		boolean pOk = Math.abs(pd) <= CameraLockPlugin.PITCH_TOLERANCE;
		boolean zOk = Math.abs(zd) <= CameraLockPlugin.ZOOM_TOLERANCE;

		panelComponent.getChildren().clear();

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("ALIGN CAMERA")
			.color(ALIGN_ORANGE)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(target.getName())
			.leftColor(HINT_COLOR)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(yawLabel(yd, yOk))
			.leftColor(yOk ? OK_GREEN : Color.WHITE)
			.right(yOk ? "" : String.valueOf(Math.abs(yd)))
			.rightColor(HINT_COLOR)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(pitchLabel(pd, pOk))
			.leftColor(pOk ? OK_GREEN : Color.WHITE)
			.right(pOk ? "" : String.valueOf(Math.abs(pd)))
			.rightColor(HINT_COLOR)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(zoomLabel(zd, zOk))
			.leftColor(zOk ? OK_GREEN : Color.WHITE)
			.right(zOk ? "" : String.valueOf(Math.abs(zd)))
			.rightColor(HINT_COLOR)
			.build());

		return panelComponent.render(graphics);
	}

	private Dimension renderLocked(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("CAMERA LOCKED")
			.color(LOCKED_RED)
			.build());

		Keybind hotkey = config.toggleHotkey();
		if (hotkey.getKeyCode() != KeyEvent.VK_UNDEFINED)
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text(hotkey.toString().toUpperCase() + " TO TOGGLE")
				.color(HINT_COLOR)
				.build());
		}

		return panelComponent.render(graphics);
	}

	private static String yawLabel(int diff, boolean ok)
	{
		if (ok) return "✓ TURN";
		return diff > 0 ? "→ RIGHT" : "← LEFT";
	}

	private static String pitchLabel(int diff, boolean ok)
	{
		if (ok) return "✓ TILT";
		return diff > 0 ? "↑ UP" : "↓ DOWN";
	}

	private static String zoomLabel(int diff, boolean ok)
	{
		if (ok) return "✓ ZOOM";
		return diff > 0 ? "ZOOM IN" : "ZOOM OUT";
	}
}

